local fsh1 = [[
precision highp float;
varying vec2 uv0;
uniform sampler2D inputImageTexture;
uniform float progress;
uniform float intensity;

#define EMBOSS_WIDTH    0.02
#define EMBOSS_HEIGHT    0.02

vec4 sample_pixel(vec2 uv, float dx, float dy)
{
    return texture2D(inputImageTexture, uv + vec2(dx, dy));
}

void main()
{
    float kerEmboss[9];
    kerEmboss[0] = 2.0 * intensity;
    kerEmboss[1] = 0.0;
    kerEmboss[2] = 0.0;
    kerEmboss[3] = 0.0;
    kerEmboss[4] = -1.0 * intensity;
    kerEmboss[5] = 0.0;
    kerEmboss[6] = 0.0;
    kerEmboss[7] = 0.0;
    kerEmboss[8] = -1.0 * intensity;
    
    vec4 pixel_matrix[9];
    vec2 uv = uv0.xy;
    
    float dxtex = EMBOSS_WIDTH * progress;
    float dytex = EMBOSS_HEIGHT * progress;

    pixel_matrix[0].rgb = sample_pixel(uv, -dxtex, -dytex)    .rgb;
    pixel_matrix[1].rgb = sample_pixel(uv, -dxtex,     0.0)    .rgb;
    pixel_matrix[2].rgb = sample_pixel(uv, -dxtex,     dytex)    .rgb;
    pixel_matrix[3].rgb = sample_pixel(uv, 0.0,     -dytex)    .rgb;
    pixel_matrix[4].rgb = sample_pixel(uv, 0.0,     0.0)    .rgb;
    pixel_matrix[5].rgb = sample_pixel(uv, 0.0,     dytex)    .rgb;
    pixel_matrix[6].rgb = sample_pixel(uv, dxtex,     -dytex)    .rgb;
    pixel_matrix[7].rgb = sample_pixel(uv, dxtex,     0.0)    .rgb;
    pixel_matrix[8].rgb = sample_pixel(uv, dxtex,     dytex)    .rgb;
    
    for (int i=0; i<9; i++)
    {
        pixel_matrix[i].a = (pixel_matrix[i].r + pixel_matrix[i].g + pixel_matrix[i].b) / 3.;
    }
   
    float res = 0.0;
    vec3 output1 = vec3(0.0,0.0,0.0);
    for (int i=0; i<9; i++)
    {
        res += kerEmboss[i] * pixel_matrix[i].a;
        output1 += kerEmboss[i] * pixel_matrix[i].rgb;
    }
    
    float convolved = clamp(res + 0.5, 0.0 ,1.0);
    gl_FragColor = vec4(vec3(convolved) ,1.0);
    
    output1.x = clamp(output1.x + 0.5, 0.0, 1.0);
    output1.y = clamp(output1.y + 0.5, 0.0, 1.0);
    output1.z = clamp(output1.z + 0.5, 0.0, 1.0);
    
    gl_FragColor = vec4(output1,1.0);
}
]]

